import{_ as e,c as s,o as n,ag as i}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Prompts","description":"","frontmatter":{"title":"Prompts"},"headers":[],"relativePath":"general/prompts.md","filePath":"general/prompts.md","lastUpdated":null}'),r={name:"general/prompts.md"};function t(l,a,p,o,c,u){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to &quot;Prompts&quot;">​</a></h1><h2 id="admin-chat-prompts" tabindex="-1">Admin Chat Prompts <a class="header-anchor" href="#admin-chat-prompts" aria-label="Permalink to &quot;Admin Chat Prompts&quot;">​</a></h2><h3 id="welcome-individual-to-chat-via-dm" tabindex="-1">Welcome Individual to Chat (via DM) <a class="header-anchor" href="#welcome-individual-to-chat-via-dm" aria-label="Permalink to &quot;Welcome Individual to Chat (via DM)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Welcome to the IrregularChat! We recommend muting the chat and checking in periodically, as the conversation can be overwhelming for some, and users are from different time zones.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A lot of resources, guides, and discussions have already been posted, and you can find them at:</span></span>
<span class="line"><span>https://irregularpedia.org</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>Here&#39;s the Irregular Chat Login guide that should walk you step by step on joining the SSO:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://irregularpedia.org/community/join</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you prefer a video guide:</span></span>
<span class="line"><span>- http://url.irregular.chat/video-guide-sso-invite</span></span>
<span class="line"><span></span></span>
<span class="line"><span>After the first step, you&#39;ll need this disposable Invite Link: http://url.irregular.chat/sso-invite</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="ask-individuals-to-introduce-themselves" tabindex="-1">Ask Individuals to Introduce Themselves <a class="header-anchor" href="#ask-individuals-to-introduce-themselves" aria-label="Permalink to &quot;Ask Individuals to Introduce Themselves&quot;">​</a></h3><h3 id="tech-chat" tabindex="-1">Tech Chat <a class="header-anchor" href="#tech-chat" aria-label="Permalink to &quot;Tech Chat&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Welcome to the chat; please take a moment to look through the user list and introduce yourself to the group.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Let us know what tech training, interests, and projects you have, and feel free to self-promote during your introduction.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Check out some resources for learning shared with the group: https://irregularpedia.org/general/learning</span></span>
<span class="line"><span>Sharing up to CUI - https://url.irregular.chat/msuite</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You&#39;ll be receiving a unique invite link to the Irregular Chat Login in DM</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="influence-chat" tabindex="-1">Influence Chat <a class="header-anchor" href="#influence-chat" aria-label="Permalink to &quot;Influence Chat&quot;">​</a></h3><h4 id="request-to-join" tabindex="-1">Request to Join <a class="header-anchor" href="#request-to-join" aria-label="Permalink to &quot;Request to Join&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You&#39;ve requested to join the Influence chat. This is heavy with INTEL and PSYOP; is this your background or focus?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="greeting" tabindex="-1">Greeting <a class="header-anchor" href="#greeting" aria-label="Permalink to &quot;Greeting&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Welcome to the chat; please take a moment to look around and introduce yourself to the group.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>We love reading articles, dissertations, and white papers on influence, behavior change models, social movements, and related studies or news; please share something with the group.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Check out some resources for learning shared with the group: https://irregularpedia.org/general/learning</span></span>
<span class="line"><span>Sharing up to CUI - https://url.irregular.chat/msuite</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You&#39;ll be receiving a unique invite link to the Irregular Chat Login in DM</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="innovation-chat" tabindex="-1">Innovation Chat <a class="header-anchor" href="#innovation-chat" aria-label="Permalink to &quot;Innovation Chat&quot;">​</a></h3><h4 id="bonafide" tabindex="-1">Bonafide <a class="header-anchor" href="#bonafide" aria-label="Permalink to &quot;Bonafide&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You requested to join the innovation chat. Are you currently in a unit supporting 1SFC or USASOC? All chat members have been validated.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you don&#39;t reply to this message in 24 hours, your request will be rejected, and you can request again when you are ready.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="greeting-1" tabindex="-1">Greeting <a class="header-anchor" href="#greeting-1" aria-label="Permalink to &quot;Greeting&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Welcome to the unofficial 1SFC/USASOC Innovation Chat, Focused on efforts that benefit the command and units directly.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please take a moment to introduce yourself and include at least the following:</span></span>
<span class="line"><span>### What innovative projects are you or your unit currently exploring?</span></span>
<span class="line"><span>    2.  Have you identified capability gaps that might impact your unit or mission?</span></span>
<span class="line"><span>    3. What do you understand the process for submitting innovation requirements to be?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Beyond daily engagement, we’d now love to hear from you or others who may want to collaborate with your efforts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please remember that this chat is strictly for unclassified discussions. For CUI SOCOM Teams: https://go.intellink.gov/1sfc_g8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="research-amp-data-chat" tabindex="-1">Research &amp; Data Chat <a class="header-anchor" href="#research-amp-data-chat" aria-label="Permalink to &quot;Research &amp;amp; Data Chat&quot;">​</a></h3><p><a href="/research/">Page</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Welcome to the chat. Share some of your relative background, interests, and projects! What are you currently researching, and how can we help?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Remember the forum is unclassified, and use any DM for advanced sharing of PII and contact information.</span></span>
<span class="line"><span>Help Expand the known resources by reviewing:  https://irregularpedia.org/research/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Let us know what sections or resources should be included for research and planning.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You&#39;ll be receiving a unique invite link to the Irregular Chat Login in DM</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="ai-ml-chat" tabindex="-1">AI/ML Chat <a class="header-anchor" href="#ai-ml-chat" aria-label="Permalink to &quot;AI/ML Chat&quot;">​</a></h3><p>[\`\`\` Welcome to the chat. Share some of your relative background, interests, and projects!</p><p>Remember the forum is unclassified, and use any DM for advanced sharing of PII and contact information. Help Expand: AI/ML - <a href="https://irregularpedia.org/ai-ml/:" target="_blank" rel="noreferrer">https://irregularpedia.org/ai-ml/:</a> let us know what resources should be added AI/ML Learning: <a href="https://irregularpedia.org/ai-ml/ai-ml-learning" target="_blank" rel="noreferrer">https://irregularpedia.org/ai-ml/ai-ml-learning</a></p><p>You&#39;ll be receiving a unique invite link to the Irregular Chat Login in DM</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### DragonOS Chat</span></span>
<span class="line"><span>DragonOS page](/ai-ml/)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Welcome to the DragonOS chat! Feel free to ask questions, provide feedback, or just lurk. Please introduce yourself and let us know how you use DragonOS in your hobbies or work. Which SDR do you currently own?</p><ul><li>YouTube channel: <a href="https://youtube.com/@cemaxecuter7783" target="_blank" rel="noreferrer">https://youtube.com/@cemaxecuter7783</a></li><li>X: <a href="https://twitter.com/cemaxecuter" target="_blank" rel="noreferrer">https://twitter.com/cemaxecuter</a></li><li>Download ISO: <a href="https://sourceforge.net/projects/dragonos-focal/" target="_blank" rel="noreferrer">https://sourceforge.net/projects/dragonos-focal/</a></li><li>Wiki Section: <a href="https://irregularpedia.org/radio/dragonos" target="_blank" rel="noreferrer">https://irregularpedia.org/radio/dragonos</a></li></ul><p>You&#39;ll be receiving a unique invite link to the Irregular Chat Single Sign-On Server in DM</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### sUAS - Robotics and sUAS Chat</span></span>
<span class="line"><span>[page](/general/suas)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Welcome to the chat. Please share some of your relative background, interests, and projects with the community of hobbyists chatting in their free time.</p><p>Remember the forum is unclassified, and use any DM for advanced sharing of PII and contact information.</p><p>Q&amp;A, Discussions, and Announcements will be posted here for knowledge management <a href="https://github.com/orgs/irregularchat/discussions" target="_blank" rel="noreferrer">https://github.com/orgs/irregularchat/discussions</a> and some in the wiki <a href="https://irregularpedia.org/general/suas-breakdown" target="_blank" rel="noreferrer">https://irregularpedia.org/general/suas-breakdown</a></p><p>You&#39;ll be receiving a unique invite link to the Irregular Chat Login in DM</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Off-Topic Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If it&#39;s you&#39;re first day in off-topic chat, your gotta meme.</p><p>Beyond memes, this is open to creative discussion, gaming, venting, successes and failures, and back and forths, not focused on tech, influence, research, or other focused themes.</p><p>Nothing Illegal, Classified, or Unethical is allowed, but as you&#39;ll see, there is still a lot of room for fun.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Business Chat</span></span>
<span class="line"><span>[Page](/general/business)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Welcome to the Business Chat, a specialized haven for service members and veterans navigating the civilian business landscape.</p><p>Introduce yourself, share your experiences, and outline your aspirations. For archived resources, connections, and opportunities, visit <a href="https://irregularpedia.org/general/business" target="_blank" rel="noreferrer">https://irregularpedia.org/general/business</a></p><p>Previous intros can be found here: <a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">https://forum.irregularchat.com</a></p><ul><li>To edit the wiki, reply with your GitHub username. If absent, creating one is straightforward.</li></ul><p>To maintain the community&#39;s essence, avoid spam or excessive promotions</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Cert Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>📚 To kickstart or enhance your journey, we&#39;ve compiled various resources. Whether you&#39;re new or seasoned, these will surely add value:</p><ul><li>General Learning Resources: <a href="https://irregularpedia.org/general/learning" target="_blank" rel="noreferrer">https://irregularpedia.org/general/learning</a></li><li>Guides and Resources for Certification Pathways: <a href="https://irregularpedia.org/general/certifications" target="_blank" rel="noreferrer">https://irregularpedia.org/general/certifications</a></li></ul><p>💬 Introduce yourself! Share what certifications you’re pursuing, your learning methods, and any questions or insights. This chat thrives on the diverse experiences and knowledge of its members.</p><p>PS: To keep up with our discussions and resources, consider sending your GitHub username to access our collaborative spaces.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Debate Chat</span></span>
<span class="line"><span>[Page](/general/debate)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol><li>State Your Initial Position: Brief and Clear. Max Two Sentences.</li><li>Create an Ephemeral Notepad and Post the Link: <a href="https://url.irregular.chat/debate-template" target="_blank" rel="noreferrer">https://url.irregular.chat/debate-template</a></li><li>Open the Floor for Questions and join Sides from ALL.</li><li>10-Minute Argument Submission: post your argument Supporting your position.</li><li>Sides are defined. Only participants can ask questions beyond this point.</li><li>Respectful Debate: • Provide emoji to show support, questions, and objection • Only those with a stated position may make arguments. All can ask questions that can be direct but may be answered by either party. • Each side will then engage in a constructive and respectful debate. Let’s rumble!</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### FLNC Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Welcome to the FLNC chat. Please introduce yourself AND provide a piece of value you think members around Liberty would benefit from. Resources, Tips, Recommendations, Opportunities</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,53)])])}const b=e(r,[["render",t]]);export{h as __pageData,b as default};
